function Metric({icon,title,value,note,tone}:{icon:React.ReactNode;title:string;value:string|number;note:string;tone:string}){return <div className="metric-card"><div className={`metric-icon ${tone}`}>{icon}</div><span>{title}</span><strong>{value}</strong><small>{note}</small></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><Search size={25}/><b>{title}</b><p>{text}</p></div>}
function PageHeader({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:React.ReactNode}){return <div className="page-head"><div><p className="eyebrow">{eyebrow}</p><h1>{title}<span className="accent-dot">.</span></h1><p>{description}</p></div>{action}</div>}
function RowPager({total,page,onPage}:{total:number;page:number;onPage:(page:number)=>void}){
 if(total<=ROWS_PER_PAGE)return null;
 const pages=Math.ceil(total/ROWS_PER_PAGE);
 const start=(page-1)*ROWS_PER_PAGE+1;
 return <nav className="row-pager" aria-label="Table pages"><span>Rows {start}–{Math.min(total,start+ROWS_PER_PAGE-1)} of {total}</span><div><button type="button" disabled={page===1} onClick={()=>onPage(page-1)}>Previous</button><span>Page {page} / {pages}</span><button type="button" disabled={page===pages} onClick={()=>onPage(page+1)}>Next</button></div></nav>;
}
function FormRepo({submit,initial,connections}:{submit:(v:any)=>Promise<void>;initial?:Repo;connections:SCMConnection[]}){
 const [v,set]=useState({name:initial?.name||'',provider:initial?.provider||'github',provider_project_id:initial?.provider_project_id||'',scm_base_url:initial?.scm_base_url||'',scm_connection_id:initial?.scm_connection_id||'',default_branch:initial?.default_branch||'',branch_mode:initial?.default_branch_source==='manual'?'manual':'auto',owner:initial?.owner||''});
 const [check,setCheck]=useState<SCMCheck|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const changeIdentity=(key:'provider'|'provider_project_id'|'scm_base_url',value:string)=>{set({...v,[key]:value,scm_connection_id:'',default_branch:'',owner:''});setCheck(null);setError('')};
 async function testSCM(){setBusy(true);setError('');try{const result=await api<SCMCheck>('/v1/repos/inspect',{method:'POST',body:JSON.stringify({provider:v.provider,provider_project_id:v.provider_project_id,scm_base_url:v.scm_base_url,scm_connection_id:v.scm_connection_id})});setCheck(result);if(result.status==='verified')set(old=>({...old,default_branch:old.branch_mode==='manual'?old.default_branch:result.default_branch||'',owner:old.owner||result.owner||''}))}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <form onSubmit={e=>{e.preventDefault();submit(v).catch(()=>{})}}>
  <p className="eyebrow">REPOSITORY {initial?'MANAGEMENT':'ENROLLMENT'}</p><h2>{initial?'Edit repository':'Connect a repository'}</h2><p className="muted">Test SCM metadata from this PANBOX server. The protected CI runner also needs connectivity to the PANBOX API.</p>
  <label>Provider<select value={v.provider} onChange={e=>changeIdentity('provider',e.target.value)}><option value="github">GitHub</option><option value="gitlab">GitLab</option><option value="bitbucket">Bitbucket</option><option value="azure">Azure Repos</option><option value="gitea">Gitea</option><option value="generic">Other Git</option></select></label>
  <label>Display name<input required value={v.name} onChange={e=>set({...v,name:e.target.value})} placeholder="e.g. PANBOX"/></label>
  <label>SCM repository ID or path<input required value={v.provider_project_id} onChange={e=>changeIdentity('provider_project_id',e.target.value)} placeholder={v.provider==='azure'?'organization/project/repository':v.provider==='gitea'||v.provider==='generic'?'https://git.example.com/owner/repository':'owner/repository'}/></label>
  <label>SCM hosting<select value={v.scm_base_url?'self':'public'} onChange={e=>changeIdentity('scm_base_url',e.target.value==='public'?'':'https://git.example.com')}><option value="public">Public cloud</option><option value="self">Self-hosted / enterprise</option></select></label>
  {v.scm_base_url&&<label>Self-hosted HTTPS origin<input value={v.scm_base_url} onChange={e=>changeIdentity('scm_base_url',e.target.value)} placeholder="https://git.example.com"/><small>Admin must allowlist its exact host in PANBOX_SCM_ALLOWED_HOSTS. No path or credentials.</small></label>}
  {connections.some(c=>c.enabled&&c.provider===v.provider&&c.base_url===v.scm_base_url)&&<label>SCM connection<select value={v.scm_connection_id} onChange={e=>{set({...v,scm_connection_id:e.target.value});setCheck(null)}}><option value="">Auto-select available connection</option>{connections.filter(c=>c.enabled&&c.provider===v.provider&&c.base_url===v.scm_base_url).map(c=><option key={c.id} value={c.id}>{c.label}</option>)}</select></label>}
  <button className="secondary wide" type="button" disabled={!v.provider_project_id||busy} onClick={testSCM}>{busy?'Checking SCM…':'Test SCM connectivity and detect branch'}</button>
  {check&&<p className="muted small" role="status"><b>{check.status==='verified'?'Verified metadata':check.status==='reachable_no_branch'?'Git endpoint reachable':'Waiting for CI metadata'}.</b> {check.message}</p>}
  {error&&<p className="form-error" role="alert">{error}</p>}
  <label>Default branch mode<select value={v.branch_mode} onChange={e=>set({...v,branch_mode:e.target.value,default_branch:e.target.value==='auto'?(check?.default_branch||''):v.default_branch})}><option value="auto">Auto-detect from SCM</option><option value="manual">Manual override</option></select></label>
  <label>Default branch {v.branch_mode==='auto'&&!v.default_branch?'(will be learned from CI)':''}<input required={v.branch_mode==='manual'} value={v.default_branch} readOnly={v.branch_mode==='auto'} onChange={e=>set({...v,default_branch:e.target.value})} placeholder="e.g. main"/></label>
  <label>Owner (optional display label)<input value={v.owner} onChange={e=>set({...v,owner:e.target.value})} placeholder="e.g. platform-team"/></label>
  <p className="muted small">Owner is display metadata only. Private GitHub and GitLab branches are verified through a connected SCM account; CI can supply the default branch when no connection is configured. Scans still run on the CI runner.</p>
  {check&&check.status!=='verified'&&<p className="muted small">Private SCM metadata can be completed by CI. Check runner access before scanning.</p>}
  <button className="primary wide" type="submit" disabled={busy||(v.branch_mode==='manual'&&!v.default_branch)||(!initial&&!check)}>{initial?'Save repository':'Enroll repository'} <ArrowRight size={16}/></button>
 </form>
}
function SCMConnectionForm({initial,submit}:{initial:SCMConnection|null;submit:(v:any)=>Promise<void>}){
 const [v,set]=useState({provider:initial?.provider||'gitlab',label:initial?.label||'',base_url:initial?.base_url||'',enabled:initial?.enabled??true,auto_enroll:initial?.auto_enroll??true,token:'',app_id:0,installation_id:0,private_key:''});
 const [busy,setBusy]=useState(false);
 return <form className="scm-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await submit(v);set({...v,label:'',token:'',app_id:0,installation_id:0,private_key:''})}catch{}finally{setBusy(false)}}}>
  <h3>{initial?'Edit connection':'Add connection'}</h3>
  <label>Provider<select disabled={!!initial} value={v.provider} onChange={e=>set({...v,provider:e.target.value as 'gitlab'|'github'})}><option value="gitlab">GitLab service account</option><option value="github">GitHub App</option></select></label>
  <label>Label<input required maxLength={120} value={v.label} onChange={e=>set({...v,label:e.target.value})} placeholder="e.g. Engineering SCM"/></label>
  <label>Self-hosted HTTPS origin (blank for cloud)<input disabled={!!initial} value={v.base_url} onChange={e=>set({...v,base_url:e.target.value})} placeholder={v.provider==='gitlab'?'https://git.example.com':'https://github.example.com'}/></label>
  {v.provider==='gitlab'?<label>Service account token {initial?'(leave blank to keep current token)':''}<input type="password" autoComplete="off" required={!initial} value={v.token} onChange={e=>set({...v,token:e.target.value})} placeholder="Token with read_api and access to the group"/></label>:<><label>GitHub App ID {initial?'(leave blank to keep current ID)':''}<input type="number" min="1" required={!initial} value={v.app_id||''} onChange={e=>set({...v,app_id:Number(e.target.value)})}/></label><label>Installation ID<input type="number" min="1" required={!initial} value={v.installation_id||''} onChange={e=>set({...v,installation_id:Number(e.target.value)})}/></label><label>App private key (PEM) {initial?'(leave blank to keep current key)':''}<textarea required={!initial} value={v.private_key} onChange={e=>set({...v,private_key:e.target.value})} rows={4} autoComplete="off"/></label></>}
  <label><input type="checkbox" checked={v.enabled} onChange={e=>set({...v,enabled:e.target.checked})}/> Connection enabled</label>
  <label><input type="checkbox" checked={v.auto_enroll} onChange={e=>set({...v,auto_enroll:e.target.checked})}/> Automatically enroll accessible repositories on save and Sync</label>
  <p className="muted small">PANBOX tests access before saving. Credentials stay on the dashboard server and are encrypted with PANBOX_SCM_ENCRYPTION_KEY. CI uses its own checkout and PANBOX API key.</p>
  <button className="primary" disabled={busy}>{busy?'Testing SCM…':initial?'Save and test':'Connect, test and discover'}</button>
 </form>
}
function FormUser({roles,submit}:{roles:Role[];submit:(v:any)=>Promise<void>}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[role,setRole]=useState('developer');return <form onSubmit={e=>{e.preventDefault();submit({email,password,role})}}><p className="eyebrow">WORKSPACE MEMBER</p><h2>Add user</h2><label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Temporary password (12+ characters)<input type="password" minLength={12} required value={password} onChange={e=>setPassword(e.target.value)}/></label><label>Role<select value={role} onChange={e=>setRole(e.target.value)}>{roles.filter(r=>r.name!=='admin').map(r=><option key={r.name}>{r.name}</option>)}</select></label><button className="primary wide">Create user</button></form>}
function FormKey({repos,submit,ci,defaultRepo}:{repos:Repo[];submit:(v:any)=>Promise<void>;ci?:boolean;defaultRepo?:string}){
 const [v,set]=useState({kind:'api',label:ci?'CI integration':'',repository_id:defaultRepo||'',scopes:ci?['scans:write']:['repos:read'],expires_hours:720});
 const readScopes=['repos:read','scans:read','findings:read','reports:export','audit:read'];
 return <form onSubmit={e=>{e.preventDefault();submit(v)}}>{ci&&<><p className="eyebrow">CI INTEGRATION</p><h2>Create API key</h2><p className="muted">One API key with scans:write plus the PANBOX project ID. The key owner needs project access. You can restrict this key to one project below.</p></>}<div className="form-grid"><label>Key type<select disabled={!!ci} value={v.kind} onChange={e=>set({...v,kind:e.target.value,scopes:['repos:read']})}><option value="api">API key</option><option value="access">Access key</option></select></label><label>Expires after<select value={v.expires_hours} onChange={e=>set({...v,expires_hours:Number(e.target.value)})}><option value={24}>24 hours</option><option value={168}>7 days</option><option value={720}>30 days</option><option value={8760}>1 year</option></select></label></div><label>Label<input required value={v.label} onChange={e=>set({...v,label:e.target.value})} placeholder="CI production"/></label><label>Project scope<select value={v.repository_id} onChange={e=>set({...v,repository_id:e.target.value})}><option value="">All allowed projects</option>{repos.filter(r=>!r.archived).map(r=><option value={r.id} key={r.id}>{r.name}</option>)}</select></label>{!ci&&<div className="scope-grid">{PERMISSIONS.map(p=><label className="check-label" key={p}><input type="checkbox" disabled={v.kind==='access'&&!readScopes.includes(p)} checked={v.scopes.includes(p)} onChange={e=>set({...v,scopes:e.target.checked?[...v.scopes,p]:v.scopes.filter(x=>x!==p)})}/>{p}</label>)}</div>}<button className="primary wide" type="submit"><KeyRound size={16}/> Generate key</button></form>
}
function RoleEditor({roles,users,repos,submit,assign,membership}:{roles:Role[];users:User[];repos:Repo[];submit:(n:string,v:any)=>Promise<void>;assign:(id:string,roles:string[])=>Promise<void>;membership:(user:string,repo:string,enabled:boolean)=>Promise<void>}){
 const [name,setName]=useState(''),[description,setDescription]=useState(''),[perms,setPerms]=useState<string[]>([]);
 function choose(r:Role){setName(r.name);setDescription(r.description);setPerms(r.permissions)}
 return <><div className="role-chips">{roles.map(r=><button className={name===r.name?'chosen':''} key={r.name} onClick={()=>choose(r)}>{r.name}{r.name==='admin'&&<LockKeyhole size={12}/>}</button>)}</div><form onSubmit={e=>{e.preventDefault();submit(name,{description,permissions:perms})}}><label>Role name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="custom_auditor" disabled={name==='admin'}/></label><label>Description<input value={description} onChange={e=>setDescription(e.target.value)} disabled={name==='admin'}/></label><div className="scope-grid">{PERMISSIONS.map(p=><label className="check-label" key={p}><input type="checkbox" disabled={name==='admin'||p==='rbac:manage'} checked={perms.includes(p)} onChange={e=>setPerms(e.target.checked?[...perms,p]:perms.filter(x=>x!==p))}/>{p}</label>)}</div><button disabled={name==='admin'} className="primary wide">Save role</button></form><h3>User assignments</h3><div className="user-list">{users.map(u=><div key={u.id}><span>{u.email}<small>{u.roles.join(', ')}</small></span>{!u.roles.includes('admin')&&<select value={u.roles[0]||''} onChange={e=>assign(u.id,[e.target.value])}>{roles.filter(r=>r.name!=='admin').map(r=><option key={r.name}>{r.name}</option>)}</select>}</div>)}</div><h3>Repository access</h3><p className="muted small">Grant each non-admin user access to specific repositories.</p>{users.filter(u=>!u.roles.includes('admin')).map(u=><div className="membership-row" key={u.id}><b>{u.email}</b><div className="scope-grid">{repos.map(r=><label className="check-label" key={r.id}><input type="checkbox" checked={u.repositories?.includes(r.id)||false} onChange={e=>membership(u.id,r.id,e.target.checked)}/>{r.name}</label>)}</div></div>)}</>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
